import React from "react";
import "./DashboardCard.css";

// dashboardData is an array of { title, count, icon, subtitle }
const dashboardData = [
  { title: "Total Complaints", count: 128, icon: "📋", subtitle: "All time" },
  { title: "Pending", count: 34, icon: "⏳", subtitle: "Awaiting action" },
  { title: "In Progress", count: 21, icon: "🔧", subtitle: "Being resolved" },
  { title: "Resolved", count: 73, icon: "✅", subtitle: "Closed successfully" },
];

// Uses map() to dynamically generate reusable dashboard statistic cards.
function DashboardCard() {
  return (
    <div className="dashboard-card-grid">
      {dashboardData.map((item) => (
        <div className="dashboard-card" key={item.title}>
          <div className="dashboard-card-icon">{item.icon}</div>
          <div>
            <p className="dashboard-card-title">{item.title}</p>
            <p className="dashboard-card-count">{item.count}</p>
            <p className="dashboard-card-subtitle">{item.subtitle}</p>
          </div>
        </div>
      ))}
    </div>
  );
}

export default DashboardCard;
